 evidence={'build':'1003b1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; public aggregate node queues and native BTC confirmed fees; not global queue or exact latency; assumed D+2 availability, not first vintages; no accepted strategy'}
